+private func retentionShapes(_ profile: String) -> [ConcurrentShape] {
+    switch profile {
+    case "cpu-growing": return [ConcurrentShape(rows: 100_000, width: 8), ConcurrentShape(rows: 8192, width: 128), ConcurrentShape(rows: 100_000, width: 32)]
+    case "cpu-small": return [ConcurrentShape(rows: 1024, width: 8), ConcurrentShape(rows: 4096, width: 32), ConcurrentShape(rows: 8192, width: 8)]
+    case "cpu-same": return Array(repeating: ConcurrentShape(rows: 100_000, width: 32), count: 3)
+    case "cpu-sizes": return [ConcurrentShape(rows: 100_000, width: 32), ConcurrentShape(rows: 8192, width: 128), ConcurrentShape(rows: 100_000, width: 8)]
+    default: return [ConcurrentShape(rows: 16_384, width: 32), ConcurrentShape(rows: 100_000, width: 8), ConcurrentShape(rows: 1024, width: 8)]
+    }
+}
